public class Bank {
  private String bankName, area, phoneNumber;

  // Constructor
  Bank(String bankName, String area, String phoneNumber) {
    bankName = bankName;    // Confusing: Refers to the parameter, not the instance variable
    area = area;            // Same confusion
    phoneNumber = phoneNumber; // Same confusion
  }
}

public class Bank {
  private String bankName, area, phoneNumber;

  // Constructor
  Bank(String bankName, String area, String phoneNumber) {
    this.bankName = bankName;        // Refers to the instance variable
    this.area = area;                // Refers to the instance variable
    this.phoneNumber = phoneNumber;  // Refers to the instance variable
  }
}

public class Bank {
  private String bankName, area, phoneNumber;

  // Constructor using 'this' to refer to instance variables
  Bank(String bankName, String area, String phoneNumber) {
    this.bankName = bankName;        // Refers to instance variable
    this.area = area;                // Refers to instance variable
    this.phoneNumber = phoneNumber;  // Refers to instance variable
  }

  // Method to display bank details
  public void displayBankDetails() {
    System.out.println("Bank Name: " + this.bankName);
    System.out.println("Area: " + this.area);
    System.out.println("Phone Number: " + this.phoneNumber);
  }

  public static void main(String[] args) {
    Bank myBank = new Bank("IBank", "Gandhi Nagar", "9876543210");
    myBank.displayBankDetails();
  }
}

